class LRUCache:
    def __init__(self, capacity):
        self.cache = {}
        self.capacity = capacity
    def get(self, key):
        return self.cache.get(key, -1)

async function fetchWithRetry(url, retries = 3) {
  try {
    return await fetch(url);
  } catch (err) {
    if (retries === 0) throw err;
    return fetchWithRetry(url, retries - 1);
  }
}
